        {
          id = 450,
          name = "IntroTrigger",
          type = "TouchTrigger",
          shape = "rectangle",
          x = 2784,
          y = 1088,
          width = 64,
          height = 160,
          rotation = 0,
          gid = 5323,
          visible = true,
          properties = {
            ["atMostOnce"] = true,
            ["script"] = "local MessageBox = require \"actions/MessageBox\"\nlocal BlockPlayer = require \"actions/BlockPlayer\"\nlocal Serial = require \"actions/Serial\"\nlocal Parallel = require \"actions/Parallel\"\nlocal YieldUntil = require \"actions/YieldUntil\"\nlocal Ease = require \"actions/Ease\"\nlocal Wait = require \"actions/Wait\"\nlocal Do = require \"actions/Do\"\nlocal Animate = require \"actions/Animate\"\nlocal AudioFade = require \"actions/AudioFade\"\nlocal PlayAudio = require \"actions/PlayAudio\"\n\nlocal ItemType = require \"util/ItemType\"\n\nreturn function(self)\n    local translate = GameState:isEquipped(\"babyt\", ItemType.Accessory, \"Translator Collar\")\n    local walkout, walkin, sprites = scene.player:split()\n\n    return Serial {\n        Do(function()\n            if self.scene.player.doingSpecialMove then\n                self.scene.player.forceDrop = true\n                self.scene.player.stopElevating = true\n            end\n        end),\n        YieldUntil(function() return self.scene.player.doingSpecialMove == false end),\n        BlockPlayer {\n        AudioFade(\"music\", 1, 0, 1),\n        Do(function()\n            for k in pairs(GameState.party) do\n                sprites[k].x = scene.player.x - 60\n                sprites[k].y = scene.player.y - 60\n            end\n        end),\n        walkout,\n        Animate(sprites.tails.sprite, \"idleright\"),\n        Animate(sprites.babyt.sprite, \"idleright\"),\n        Wait(1),\n        MessageBox{message=\"Tails: Whoah...\"},\n\n        Ease(self.scene.camPos, \"x\", -350, 0.2, \"linear\"),\n        Wait(1),\n        PlayAudio(\"music\", \"storybooklonging\", 1, true),\n        Animate(sprites.tails.sprite, \"joyright\"),\n        Parallel {\n            sprites.tails:hop(),\n            MessageBox{message=\"Tails: There it is! {p60}{h Boulder Bay}!\"}\n        },\n        Wait(1),\n        MessageBox{message=translate and \"Baby T: Home, sweet home!\" or \"Baby T: *grunts*\"},\n        Wait(1),\n        Animate(sprites.tails.sprite, \"idleright\"),\n        MessageBox{message=\"Tails: It's just like in the story, Baby T! {p60}We'll find the Light of Mobius in no time!\", closeAction=Wait(3)},\n        Parallel {\n            AudioFade(\"music\", 0.8, 0, 1),\n            MessageBox{message=\"That's enough, you two!\"}\n        },\n        Do(function()\n            self.scene.objectLookup.B.hidden = false\n            self.scene.objectLookup.B.sprite:setAnimation(\"idleright\")\n        end),\n        Animate(sprites.tails.sprite, \"shock\"),\n        Animate(sprites.babyt.sprite, \"shock\"),\n        Parallel {\n            Ease(self.scene.camPos, \"x\", 0, 0.5, \"linear\"),\n            sprites.tails:hop(),\n            sprites.babyt:hop(),\n        },\n        Wait(1),\n        Animate(sprites.tails.sprite, \"idleleft\"),\n        Animate(sprites.babyt.sprite, \"idleleft\"),\n        PlayAudio(\"music\", \"curiosity\", 0.7, true, true),\n        Parallel {\n            sprites.tails:hop(),\n            MessageBox{message=\"Tails: B!?\"}\n        },\n        Animate(sprites.babyt.sprite, \"shock\"),\n        Parallel {\n            sprites.babyt:hop(),\n            MessageBox{message=translate and \"Baby T: Ah!! {p60}A Swatbot!\" or \"Baby T: *scared squeel*\"}\n        },\n        Animate(self.scene.objectLookup.B.sprite, \"seriousdown\"),\n        MessageBox{message=\"B: Take it easy, kid. {p60}I'm no Swatbot.\"},\n        MessageBox{message=\"Tails: Yeah, don't worry T. {p60}He's a friend.\"},\n        Animate(sprites.babyt.sprite, \"idleleft\"),\n        Wait(1),\n        Animate(self.scene.objectLookup.B.sprite, \"questionright\"),\n        MessageBox{message=\"B: And you're lucky I am! {p60}Do you know how dangerous it is to go wandering off alone?!\"},\n        Animate(sprites.tails.sprite, \"saddown\"),\n        Animate(sprites.babyt.sprite, \"saddown\"),\n        MessageBox{message=\"Tails: Yeah, I know, but--\", closeAction=Wait(1)},\n        Animate(self.scene.objectLookup.B.sprite, \"idleright\"),\n        MessageBox{message=\"B: I may not be a member of your little \\\"Freedom Team\\\", {p60}but I am your elder, {p60}and I have a responsibility to protect you...\"},\n        Animate(self.scene.objectLookup.B.sprite, \"idleright\"),\n        MessageBox{message=\"B: ...which is why I am taking you back to Knothole, Tails.\"},\n        Animate(sprites.tails.sprite, \"sadleft\"),\n        Animate(sprites.babyt.sprite, \"sadleft\"),\n        MessageBox{message=\"Tails: But-but--\", closeAction=Wait(1)},\n        MessageBox{message=\"B: No \\\"buts\\\"! {p60}Let's go.\"},\n        Parallel {\n            AudioFade(\"music\", 0.7, 0, 1),\n            PlayAudio(\"sfx\", \"elevator\", 1.0, true, true)\n        },\n        self.scene:screenShake(10, 30, 20),\n        AudioFade(\"sfx\", 1, 0, 1),\n\n        -- Terrabot shows up\n        Do(function()\n            self.scene.objectLookup.Terrabot.hidden = false\n            self.scene.objectLookup.Terrabot.y = self.scene.objectLookup.Terrabot.y - 400\n            GameState:addToParty(\"b\", 1, true)\n        end),\n        Ease(self.scene.objectLookup.Terrabot, \"y\", function() return self.scene.objectLookup.Terrabot.y + 400 end, 6, \"quad\"),\n        Parallel {\n            Ease(self.scene.camPos, \"x\", 200, 1, \"linear\"),\n            PlayAudio(\"sfx\", \"juggerbotstep\", 1.0, true),\n            self.scene:screenShake(20, 30, 3)\n        },\n        PlayAudio(\"music\", \"robotrouble\", 1.0, true),\n        Animate(sprites.tails.sprite, \"shock\"),\n        Animate(sprites.babyt.sprite, \"shock\"),\n        Animate(self.scene.objectLookup.B.sprite, \"shock\"),\n        Parallel {\n            sprites.tails:hop(),\n            sprites.babyt:hop(),\n            self.scene.objectLookup.B:hop(),\n            MessageBox{message=\"Tails: What the heck is that?!\", closeAction=Wait(1)}\n        },\n        Do(function()\n            self.scene.audio:stopMusic()\n        end),\n        self.scene:enterBattle{\n            opponents = {\"terrabot\"},\n            initiative = \"cinematic\",\n            quiet = true\n        }\n    }}\nend"
